{"meetingId": "648", "tickets": [
{"title": "Restore secure online access for Lena Copperwisp", "text": "Restore Lena Copperwisp's Velvet Acorn Custody portal access using a secure method that does not rely on the old SMS code path, after she was locked out following repeated unexpected multifactor authentication prompts.", "priority": null, "dueDate": "2025-04-10", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the agreed follow-up is to restore secure online access by April 10, 2025."},
{"title": "Review unrecognized external bank link", "text": "Review the pending external bank nickname on the Velvet Acorn Custody activity view for Lena Copperwisp's joint taxable account that she did not recognize, and reconcile the difference between her known instructions and the account record.", "priority": null, "dueDate": "2025-04-11", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the agreed follow-up is to review that link by April 11, 2025."},
{"title": "Update recurring payment instructions", "text": "Pause the recurring $2,500 monthly transfer from Lena and Noah Copperwisp's joint taxable account at Velvet Acorn Custody to their Teacup Comet Bank checking account until replacement instructions use only a verified Teacup Comet Bank destination with phone confirmation before money movement.", "priority": null, "dueDate": "2025-04-14", "assigneeId": null, "templateId": "37c17d04-e353-50f8-a3c6-359f520559a4", "subTasks": [], "evidence": "the agreed follow-up is to update the instructions by April 14, 2025."},
{"title": "Collect bank incident documentation", "text": "Collect from Lena Copperwisp the Teacup Comet Bank incident reference, statement pages showing any attempted micro-deposits, and written confirmation of which bank account numbers remain valid.", "priority": null, "dueDate": "2025-04-15", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the agreed follow-up is to collect those materials by April 15, 2025."},
{"title": "Refresh account safeguards and trusted contact records", "text": "Update the Velvet Acorn Custody alert and trusted contact records for Lena Copperwisp to replace her prior work email and add Noah Copperwisp's current mobile number as a trusted contact verification option.", "priority": null, "dueDate": "2025-04-18", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the agreed follow-up is to refresh those records by April 18, 2025."},
{"title": "Coordinate secure tuition funding", "text": "Coordinate secure funding of the $8,600 spring tuition installment for Poppy Copperwisp at Marzipan Meadow School before the next normal advisory service cycle, ensuring funds are not routed through any unverified destination account.", "priority": null, "dueDate": "2025-04-16", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "the agreed follow-up is to coordinate secure tuition funding by April 16, 2025."}
]}
